scripts.script:
import java.nio.file.*

def srcDir = new File(project.build.directory, 'generated-sources/fixes')

def patches = [
  // Make invoke() public so KaModCommandFix can call it directly without reflection
  [file: 'org/jetbrains/kotlin/idea/codeinsight/api/applicable/intentions/KotlinPsiUpdateModCommandAction.kt',
   old:  'protected abstract fun invoke(',
   new_: 'public abstract fun invoke('],
]

// Remove the Contextless inner class from KotlinPsiUpdateModCommandAction —
// we only use ElementBased and ClassBased. ClassBased is kept because
// KotlinApplicableModCommandAction extends it; its ContextProvider /
// getElementContext / KtElement references are now satisfiable because
// ContextProvider.kt is compiled in this module (see the patch section below).
def modCommandFile = new File(srcDir,
  'org/jetbrains/kotlin/idea/codeinsight/api/applicable/intentions/KotlinPsiUpdateModCommandAction.kt')
if (modCommandFile.exists()) {
  def lines = modCommandFile.readLines()
  def out = []
  def skipClassMarkers = ['abstract class Contextless']
  def inSkippedClass = false
  def braceDepth = 0
  lines.each { line ->
    if (!inSkippedClass && skipClassMarkers.any { line.contains(it) }) {
      inSkippedClass = true
      braceDepth = 0
    }
    if (inSkippedClass) {
      braceDepth += line.count('{') - line.count('}')
      if (braceDepth <= 0 && line.contains('}')) { inSkippedClass = false }
      return
    }
    out << line
  }
  modCommandFile.text = out.join('\n')
  log.info("Removed Contextless from KotlinPsiUpdateModCommandAction.kt")
}

patches.each { p ->
  def f = new File(srcDir, p.file)
  if (!f.exists()) { log.warn("patch target not found: ${p.file}"); return }
  def text = f.text
  if (!text.contains(p.old)) { log.warn("patch target not found in ${p.file}: '${p.old}'"); return }
  f.text = text.replace(p.old, p.new_)
  log.info("Patched ${p.file}")
}

// AddAccessorUtils: replace 'startOffset' extension (not on classpath) with 'textRange.startOffset'
def addAccessorUtilsFile = new File(srcDir,
  'org/jetbrains/kotlin/idea/codeinsights/impl/base/intentions/AddAccessorUtils.kt')
if (addAccessorUtilsFile.exists()) {
  def text = addAccessorUtilsFile.text
  text = text.replace('import org.jetbrains.kotlin.psi.psiUtil.startOffset\n', '')
  text = text.replace('.startOffset', '.textRange.startOffset')
  addAccessorUtilsFile.text = text
  log.info("Patched AddAccessorUtils.kt: removed startOffset import, use textRange.startOffset")
}

// AddJvmInlineAnnotationFix: replace 'addAnnotation(ClassId)' (from base/code-insight, not on classpath)
// with direct KtPsiFactory annotation entry creation. Era 253 uses StandardKotlinNames.Jvm.JvmInline.
def addJvmInlineFile = new File(srcDir, 'org/jetbrains/kotlin/idea/quickfix/AddJvmInlineAnnotationFix.kt')
if (addJvmInlineFile.exists()) {
  def text = addJvmInlineFile.text
  text = text.replace('import org.jetbrains.kotlin.idea.util.addAnnotation\n', '')
  text = text.replace('import org.jetbrains.kotlin.name.ClassId\n', '')
  text = text.replace('import org.jetbrains.kotlin.idea.codeinsight.utils.StandardKotlinNames\n', '')
  // Era 222 body (kept for safety — no-op on era 253)
  text = text.replace('import org.jetbrains.kotlin.name.FqName\n', '')
  text = text.replace(
    '''        val jvmInlineFqName = FqName("kotlin.jvm.JvmInline")
        val jvmInlineClassId = ClassId.topLevel(jvmInlineFqName)
        element.addAnnotation(jvmInlineClassId)''',
    '''        element.addAnnotationEntry(KtPsiFactory(actionContext.project).createAnnotationEntry("@kotlin.jvm.JvmInline"))'''
  )
  // Era 253 body
  text = text.replace(
    '''        val jvmInlineClassId = ClassId.topLevel(StandardKotlinNames.Jvm.JvmInline)
        element.addAnnotation(jvmInlineClassId)''',
    '''        element.addAnnotationEntry(KtPsiFactory(actionContext.project).createAnnotationEntry("@kotlin.jvm.JvmInline"))'''
  )
  // add KtPsiFactory import if not already present
  if (!text.contains('import org.jetbrains.kotlin.psi.KtPsiFactory')) {
    text = text.replace('import org.jetbrains.kotlin.psi.KtClass\n',
                        'import org.jetbrains.kotlin.psi.KtClass\nimport org.jetbrains.kotlin.psi.KtPsiFactory\n')
  }
  addJvmInlineFile.text = text
  log.info("Patched AddJvmInlineAnnotationFix.kt: replaced addAnnotation(ClassId) with KtPsiFactory")
}

// AddReturnExpressionFix: remove safeAs and endOffset (not on classpath); simplify invoke body.
def addReturnExprFile = new File(srcDir, 'org/jetbrains/kotlin/idea/quickfix/AddReturnExpressionFix.kt')
if (addReturnExprFile.exists()) {
  def text = addReturnExprFile.text
  text = text.replace('import org.jetbrains.kotlin.psi.psiUtil.endOffset\n', '')
  text = text.replace('import org.jetbrains.kotlin.utils.addToStdlib.safeAs\n', '')
  text = text.replace('import org.jetbrains.kotlin.psi.KtReturnExpression\n', '')
  // Replace the body: remove safeAs cast, updater.select, updater.moveCaretTo
  text = text.replace(
    '''        val returnExpression = psiFactory.createExpression("return TODO(\\"${KotlinBundle.message("provide.return.value")}\\")")
        val todo = bodyBlock.addBefore(returnExpression, rBrace).safeAs<KtReturnExpression>()?.returnedExpression ?: return
        updater.select(todo)
        updater.moveCaretTo(todo.endOffset)''',
    '''        val returnExpression = psiFactory.createExpression("return TODO(\\"Provide return value\\")")
        bodyBlock.addBefore(returnExpression, rBrace)'''
  )
  addReturnExprFile.text = text
  log.info("Patched AddReturnExpressionFix.kt: removed safeAs/endOffset, simplified invoke body")
}

// ---------------------------------------------------------------------------
// E10 (J2K): the frontend-independent RemoveExclExclCallFix / RemoveUselessCastFix
// extend the *classic* quick-fix API (org.jetbrains.kotlin.idea.codeinsight.api.classic.
// quickfixes.{CleanupFix, PsiElementSuitabilityCheckers, QuickFixesPsiBasedFactory}), which
// depends on the whole inspection/cleanup subsystem this plugin does not bundle. J2K only
// needs the static `invoke(...)` mutation, so the factory companion is dropped and the
// `CleanupFix.ModCommand` supertype removed. Behaviour of the mutation itself is unchanged;
// RemoveUselessCastFix's `replaced(...).dropEnclosingParenthesesIfPossible()` pair (base/psi
// extensions) is inlined with the same effect.
// ---------------------------------------------------------------------------
def removeExclExclFile = new File(srcDir, 'org/jetbrains/kotlin/idea/quickfix/RemoveExclExclCallFix.kt')
if (removeExclExclFile.exists()) {
  def text = removeExclExclFile.text
  text = text.replace('import com.intellij.codeInsight.intention.IntentionAction\n', '')
  text = text.replace('import org.jetbrains.kotlin.idea.codeinsight.api.classic.quickfixes.CleanupFix\n', '')
  text = text.replace('import org.jetbrains.kotlin.idea.codeinsight.api.classic.quickfixes.PsiElementSuitabilityCheckers\n', '')
  text = text.replace('import org.jetbrains.kotlin.idea.codeinsight.api.classic.quickfixes.QuickFixesPsiBasedFactory\n', '')
  text = text.replace('import org.jetbrains.kotlin.psi.psiUtil.getNonStrictParentOfType\n', '')
  text = text.replace(') : PsiUpdateModCommandAction<PsiElement>(element), CleanupFix.ModCommand {',
                      ') : PsiUpdateModCommandAction<PsiElement>(element) {')
  text = text.replace(
    '''    companion object : QuickFixesPsiBasedFactory<PsiElement>(PsiElement::class, PsiElementSuitabilityCheckers.ALWAYS_SUITABLE) {
        fun invoke(element: PsiElement) {
            val postfixExpression = element as? KtPostfixExpression ?: return
            val baseExpression = postfixExpression.baseExpression ?: return
            postfixExpression.replace(baseExpression)
        }

        override fun doCreateQuickFix(psiElement: PsiElement): List<IntentionAction> {
            val postfixExpression = psiElement.getNonStrictParentOfType<KtPostfixExpression>() ?: return emptyList()
            return listOfNotNull(RemoveExclExclCallFix(postfixExpression).asIntention())
        }
    }''',
    '''    companion object {
        fun invoke(element: PsiElement) {
            val postfixExpression = element as? KtPostfixExpression ?: return
            val baseExpression = postfixExpression.baseExpression ?: return
            postfixExpression.replace(baseExpression)
        }
    }''')
  removeExclExclFile.text = text
  log.info("Patched RemoveExclExclCallFix.kt: dropped classic quick-fix factory companion")
}

def removeUselessCastFile = new File(srcDir, 'org/jetbrains/kotlin/idea/quickfix/RemoveUselessCastFix.kt')
if (removeUselessCastFile.exists()) {
  def text = removeUselessCastFile.text
  text = text.replace('import com.intellij.codeInsight.intention.IntentionAction\n', '')
  text = text.replace('import org.jetbrains.kotlin.idea.base.psi.dropEnclosingParenthesesIfPossible\n', '')
  text = text.replace('import org.jetbrains.kotlin.idea.base.psi.replaced\n', '')
  text = text.replace('import org.jetbrains.kotlin.idea.codeinsight.api.classic.quickfixes.CleanupFix\n', '')
  text = text.replace('import org.jetbrains.kotlin.idea.codeinsight.api.classic.quickfixes.PsiElementSuitabilityCheckers\n', '')
  text = text.replace('import org.jetbrains.kotlin.idea.codeinsight.api.classic.quickfixes.QuickFixesPsiBasedFactory\n', '')
  text = text.replace('import org.jetbrains.kotlin.psi.psiUtil.getNonStrictParentOfType\n', '')
  text = text.replace('import org.jetbrains.kotlin.psi.KtExpression\n',
                      'import org.jetbrains.kotlin.psi.KtExpression\nimport org.jetbrains.kotlin.psi.KtParenthesizedExpression\n')
  text = text.replace('''class RemoveUselessCastFix(element: KtBinaryExpressionWithTypeRHS) : PsiUpdateModCommandAction<KtBinaryExpressionWithTypeRHS>(element),
                                                                     CleanupFix.ModCommand {''',
                      '''class RemoveUselessCastFix(element: KtBinaryExpressionWithTypeRHS) : PsiUpdateModCommandAction<KtBinaryExpressionWithTypeRHS>(element) {''')
  text = text.replace(
    '''    companion object : QuickFixesPsiBasedFactory<PsiElement>(PsiElement::class, PsiElementSuitabilityCheckers.ALWAYS_SUITABLE) {
        operator fun invoke(element: KtBinaryExpressionWithTypeRHS): KtExpression = element.replaced(element.left).dropEnclosingParenthesesIfPossible()

        override fun doCreateQuickFix(psiElement: PsiElement): List<IntentionAction> {
            val expression = psiElement.getNonStrictParentOfType<KtBinaryExpressionWithTypeRHS>() ?: return emptyList()
            return listOf(
                RemoveUselessCastFix(expression).asIntention()
            )
        }
    }''',
    '''    companion object {
        operator fun invoke(element: KtBinaryExpressionWithTypeRHS): KtExpression {
            val left = element.left ?: return element
            val replaced = element.replace(left)
            return if (replaced is KtParenthesizedExpression) replaced.expression ?: replaced
            else replaced as? KtExpression ?: left
        }
    }''')
  removeUselessCastFile.text = text
  log.info("Patched RemoveUselessCastFix.kt: dropped classic quick-fix factory companion, inlined replaced()")
}

// ---------------------------------------------------------------------------
// code-insight/api applicable/** framework (used by the K2 inspections and
// intentions in the KotlinCodeInsightImpl module).
//
// The framework is compiled standalone here, without the surrounding
// code-insight modules. Two kinds of references are absent from this
// classpath and are patched out:
//   * org.jetbrains.kotlin.idea.codeinsight.api.applicable.extensions.*
//     (KaDanglingFileResolutionModeProvider) and analyzeCopy / copyOrigin —
//     only needed for injected/dangling files, which this standalone
//     container never produces.
//   * org.jetbrains.kotlin.analysis.api.permissions.forbidAnalysis —
//     a development-time assertion helper; inlining its body keeps the
//     "no analysis on EDT" guard semantics without the dependency.
// ---------------------------------------------------------------------------

// ApplicabilityRange.kt: textRangeIn lives in base/psi, which is not a dependency here.
def applicabilityRangeFile = new File(srcDir,
  'org/jetbrains/kotlin/idea/codeinsight/api/applicators/ApplicabilityRange.kt')
if (applicabilityRangeFile.exists()) {
  def text = applicabilityRangeFile.text
  text = text.replace('import org.jetbrains.kotlin.idea.base.psi.textRangeIn\n', '')
  text = text.replace('it.textRangeIn(element)',
    'com.intellij.openapi.util.TextRange(it.textRange.startOffset - element.textRange.startOffset, it.textRange.endOffset - element.textRange.startOffset)')
  applicabilityRangeFile.text = text
  log.info("Patched ApplicabilityRange.kt: inlined textRangeIn")
}

// ContextProvider.kt: drop analyzeCopy/copyOrigin (injected-file support).
def contextProviderFile = new File(srcDir,
  'org/jetbrains/kotlin/idea/codeinsight/api/applicable/ContextProvider.kt')
if (contextProviderFile.exists()) {
  def text = contextProviderFile.text
  text = text.replace('import org.jetbrains.kotlin.analysis.api.analyzeCopy\n', '')
  text = text.replace('import org.jetbrains.kotlin.analysis.api.projectStructure.copyOrigin\n', '')
  text = text.replace('import org.jetbrains.kotlin.idea.codeinsight.api.applicable.extensions.KaDanglingFileResolutionModeProvider\n', '')
  text = text.replace(
    '''@OptIn(KaExperimentalApi::class)
fun <E : KtElement, C : Any> ContextProvider<E, C>.getElementContext(
    element: E,
): C? = if (element.containingFile.copyOrigin == null) analyze(element) {
    prepareContext(element)
} else analyzeCopy(
    element,
    KaDanglingFileResolutionModeProvider.getDanglingFileResolutionMode(element)
) {
    prepareContext(element)
}''',
    '''@OptIn(KaExperimentalApi::class)
fun <E : KtElement, C : Any> ContextProvider<E, C>.getElementContext(
    element: E,
): C? = analyze(element) {
    prepareContext(element)
}''')
  contextProviderFile.text = text
  log.info("Patched ContextProvider.kt: dropped dangling-file support")
}

// KotlinApplicableInspectionBase.kt: inline forbidAnalysis.
def applicableInspectionFile = new File(srcDir,
  'org/jetbrains/kotlin/idea/codeinsight/api/applicable/inspections/KotlinApplicableInspectionBase.kt')
if (applicableInspectionFile.exists()) {
  def text = applicableInspectionFile.text
  text = text.replace('import org.jetbrains.kotlin.analysis.api.permissions.forbidAnalysis\n', '')
  text = text.replace('forbidAnalysis("isApplicableByPsi") {', 'run {')
  text = text.replace('forbidAnalysis("getApplicabilityRanges") {', 'run {')
  applicableInspectionFile.text = text
  log.info("Patched KotlinApplicableInspectionBase.kt: inlined forbidAnalysis")
}

// KotlinApplicableModCommandAction.kt: inline forbidAnalysis and widen isElementApplicable.
// `isElementApplicable` is `protected final` in the IDEA source; the NetBeans adapter layer
// lives in a different module and must call it to drive applicability, so it is made public.
def applicableModCommandFile = new File(srcDir,
  'org/jetbrains/kotlin/idea/codeinsight/api/applicable/intentions/KotlinApplicableModCommandAction.kt')
if (applicableModCommandFile.exists()) {
  def text = applicableModCommandFile.text
  text = text.replace('import org.jetbrains.kotlin.analysis.api.permissions.forbidAnalysis\n', '')
  text = text.replace('forbidAnalysis("isApplicableByPsi") {', 'run {')
  text = text.replace('forbidAnalysis("getApplicabilityRanges") {', 'run {')
  text = text.replace('\n    final override fun isElementApplicable(', '\n    public final override fun isElementApplicable(')
  applicableModCommandFile.text = text
  log.info("Patched KotlinApplicableModCommandAction.kt: inlined forbidAnalysis, widened isElementApplicable")
}
